## Instalación

```bash
pip install pytest pytest-mock pytest-cov
```

- **pytest**: el estándar de facto para pruebas en Python; sus fixtures son más flexibles que `setUp`/`tearDown` de `unittest`.
- **pytest-mock**: añade la fixture `mocker` para hacer mocks con limpieza automática.
- **pytest-cov**: informe de cobertura de código.

## Código completo (`test_inventario.py`)

```python
"""
Ejemplo completo de pruebas unitarias con fixtures en pytest.

Ejecutar:
    pytest -v test_inventario.py
    pytest -v --cov=. --cov-report=term-missing test_inventario.py
"""
import json
import sqlite3
from dataclasses import dataclass, field

import pytest


# ---------------------------------------------------------------------------
# Código a probar (en un proyecto real estaría en su propio módulo)
# ---------------------------------------------------------------------------

class StockInsuficienteError(Exception):
    pass


@dataclass
class Producto:
    nombre: str
    precio: float
    cantidad: int = 0


@dataclass
class Inventario:
    productos: dict[str, Producto] = field(default_factory=dict)

    def agregar(self, producto: Producto) -> None:
        if producto.precio < 0:
            raise ValueError("El precio no puede ser negativo")
        self.productos[producto.nombre] = producto

    def retirar(self, nombre: str, cantidad: int) -> None:
        producto = self.productos[nombre]
        if cantidad > producto.cantidad:
            raise StockInsuficienteError(
                f"Stock insuficiente de {nombre}: {producto.cantidad} < {cantidad}"
            )
        producto.cantidad -= cantidad

    def valor_total(self) -> float:
        return sum(p.precio * p.cantidad for p in self.productos.values())

    def exportar_json(self, ruta) -> None:
        datos = [vars(p) for p in self.productos.values()]
        ruta.write_text(json.dumps(datos, ensure_ascii=False), encoding="utf-8")


class RepositorioProductos:
    """Persistencia en SQLite."""

    def __init__(self, conexion: sqlite3.Connection):
        self.conexion = conexion
        self.conexion.execute(
            "CREATE TABLE IF NOT EXISTS productos "
            "(nombre TEXT PRIMARY KEY, precio REAL, cantidad INTEGER)"
        )

    def guardar(self, producto: Producto) -> None:
        self.conexion.execute(
            "INSERT OR REPLACE INTO productos VALUES (?, ?, ?)",
            (producto.nombre, producto.precio, producto.cantidad),
        )
        self.conexion.commit()

    def obtener(self, nombre: str) -> Producto | None:
        fila = self.conexion.execute(
            "SELECT nombre, precio, cantidad FROM productos WHERE nombre = ?",
            (nombre,),
        ).fetchone()
        return Producto(*fila) if fila else None


class ServicioPrecios:
    """Depende de un cliente HTTP externo (se mockea en las pruebas)."""

    def __init__(self, cliente_http):
        self.cliente_http = cliente_http

    def precio_con_descuento(self, nombre: str) -> float:
        respuesta = self.cliente_http.get(f"/precios/{nombre}")
        return round(respuesta["precio"] * (1 - respuesta["descuento"]), 2)


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------

@pytest.fixture
def producto_basico():
    """Fixture simple: devuelve un objeto nuevo para cada prueba."""
    return Producto(nombre="Teclado", precio=50.0, cantidad=10)


@pytest.fixture
def inventario(producto_basico):
    """Fixture que depende de otra fixture."""
    inv = Inventario()
    inv.agregar(producto_basico)
    inv.agregar(Producto(nombre="Ratón", precio=20.0, cantidad=5))
    return inv


@pytest.fixture(scope="module")
def conexion_db():
    """
    Fixture con alcance de módulo y teardown mediante yield:
    la conexión se crea una sola vez para todas las pruebas del archivo.
    """
    conexion = sqlite3.connect(":memory:")
    yield conexion
    conexion.close()


@pytest.fixture
def repositorio(conexion_db):
    """Aísla cada prueba: limpia la tabla al terminar."""
    repo = RepositorioProductos(conexion_db)
    yield repo
    conexion_db.execute("DELETE FROM productos")
    conexion_db.commit()


@pytest.fixture(params=[
    (100.0, 0.10, 90.0),
    (59.99, 0.25, 44.99),
    (10.0, 0.0, 10.0),
], ids=["10%", "25%", "sin-descuento"])
def caso_descuento(request):
    """Fixture parametrizada: cada prueba que la use se ejecuta 3 veces."""
    return request.param


@pytest.fixture
def cliente_http_falso(mocker):
    """Usa la fixture `mocker` de pytest-mock; se restaura sola."""
    return mocker.Mock()


@pytest.fixture
def crear_producto():
    """Patrón 'factory as fixture': permite crear varios objetos a medida."""
    creados = []

    def _crear(nombre="Genérico", precio=1.0, cantidad=1):
        producto = Producto(nombre, precio, cantidad)
        creados.append(producto)
        return producto

    yield _crear
    creados.clear()


# ---------------------------------------------------------------------------
# Pruebas
# ---------------------------------------------------------------------------

class TestInventario:

    def test_agregar_producto(self, inventario):
        inventario.agregar(Producto("Monitor", 200.0, 2))
        assert "Monitor" in inventario.productos
        assert len(inventario.productos) == 3

    def test_precio_negativo_lanza_error(self, inventario):
        with pytest.raises(ValueError, match="negativo"):
            inventario.agregar(Producto("Roto", -1.0))

    def test_retirar_reduce_stock(self, inventario):
        inventario.retirar("Teclado", 3)
        assert inventario.productos["Teclado"].cantidad == 7

    def test_retirar_sin_stock_suficiente(self, inventario):
        with pytest.raises(StockInsuficienteError):
            inventario.retirar("Ratón", 99)

    def test_valor_total(self, inventario):
        assert inventario.valor_total() == pytest.approx(50.0 * 10 + 20.0 * 5)

    def test_fixtures_son_independientes(self, inventario, producto_basico):
        # pytest reutiliza la misma instancia dentro de una prueba...
        assert inventario.productos["Teclado"] is producto_basico
        # ...pero la modificación de otra prueba no se filtra aquí.
        assert producto_basico.cantidad == 10

    def test_exportar_json(self, inventario, tmp_path):
        # tmp_path es una fixture integrada: directorio temporal único.
        archivo = tmp_path / "inventario.json"
        inventario.exportar_json(archivo)

        datos = json.loads(archivo.read_text(encoding="utf-8"))
        nombres = {p["nombre"] for p in datos}
        assert nombres == {"Teclado", "Ratón"}

    def test_factory_fixture(self, crear_producto):
        inv = Inventario()
        for i in range(3):
            inv.agregar(crear_producto(nombre=f"P{i}", precio=2.0, cantidad=i))
        assert inv.valor_total() == pytest.approx(2.0 * (0 + 1 + 2))


class TestRepositorio:

    def test_guardar_y_obtener(self, repositorio, producto_basico):
        repositorio.guardar(producto_basico)
        assert repositorio.obtener("Teclado") == producto_basico

    def test_obtener_inexistente(self, repositorio):
        # Pasa gracias al teardown de la fixture `repositorio`.
        assert repositorio.obtener("Teclado") is None


class TestServicioPrecios:

    def test_precio_con_descuento(self, cliente_http_falso, caso_descuento):
        precio, descuento, esperado = caso_descuento
        cliente_http_falso.get.return_value = {"precio": precio, "descuento": descuento}

        servicio = ServicioPrecios(cliente_http_falso)

        assert servicio.precio_con_descuento("Teclado") == esperado
        cliente_http_falso.get.assert_called_once_with("/precios/Teclado")

    def test_error_de_red_se_propaga(self, cliente_http_falso):
        cliente_http_falso.get.side_effect = ConnectionError("sin red")
        servicio = ServicioPrecios(cliente_http_falso)

        with pytest.raises(ConnectionError):
            servicio.precio_con_descuento("Teclado")


@pytest.mark.parametrize("cantidad, valido", [(0, True), (10, True), (11, False)])
def test_limites_de_retiro(inventario, cantidad, valido):
    """Combinación de parametrize con fixtures."""
    if valido:
        inventario.retirar("Teclado", cantidad)
    else:
        with pytest.raises(StockInsuficienteError):
            inventario.retirar("Teclado", cantidad)
```

## Ejecución

```bash
pytest -v test_inventario.py
pytest -v --cov=. --cov-report=term-missing test_inventario.py
pytest --fixtures-per-test test_inventario.py   # muestra qué fixtures usa cada prueba
```

## Tipos de fixture incluidos

| Fixture | Concepto |
|---|---|
| `producto_basico` | Fixture simple, se crea de nuevo en cada prueba |
| `inventario` | Fixture que depende de otra fixture |
| `conexion_db` | `scope="module"` + teardown con `yield` |
| `repositorio` | Limpieza tras cada prueba para mantenerlas aisladas |
| `caso_descuento` | Fixture parametrizada con `params` e `ids` |
| `cliente_http_falso` | Mock con `mocker` (pytest-mock) |
| `crear_producto` | Patrón *factory as fixture* |
| `tmp_path` | Fixture integrada de pytest |

En un proyecto real, mueve las fixtures compartidas a un archivo `conftest.py`. pytest las detecta automáticamente, sin necesidad de importarlas.
